  1350  /*  Is this rel/rela section related to dwarf at all?
  1351      set oksecnum zero if not. Else set targ secnum.
  1352      Never returns DW_DLV_NO_ENTRY. */
  1353  static int
  1354  this_rel_is_a_section_dwarf_related(
  1355      dwarf_elf_object_access_internals_t *ep,
  1356      struct generic_shdr *gshdr,
  1357      unsigned *oksecnum_out,
  1358      int *errcode)
  1359  {
  1360      unsigned oksecnum = 0;
  1361      struct generic_shdr *gstarg = 0;
  1362
  1363      if (gshdr->gh_type != SHT_RELA &&
  1364          gshdr->gh_type != SHT_REL)  {
  1365          *oksecnum_out = 0;
  1366          return DW_DLV_OK;
  1367      }
  1368      oksecnum = gshdr->gh_reloc_target_secnum;
  1369      if (oksecnum >= ep->f_loc_shdr.g_count) {
  1370          *oksecnum_out = 0;
  1371          *errcode = DW_DLE_ELF_SECTION_ERROR;
  1372          return DW_DLV_ERROR;
  1373      }
  1374      gstarg = ep->f_shdr+oksecnum;
  1375      if (!gstarg->gh_is_dwarf) {
  1376          *oksecnum_out = 0; /* no reloc needed. */
  1377          return DW_DLV_OK;
  1378      }
  1379      *oksecnum_out = oksecnum;
  1380      return DW_DLV_OK;
  1381  }
