  1383      the target of the relocations.
  1384      This also loads .rel. */
  1385  int
  1386  _dwarf_load_elf_relx(
  1387      dwarf_elf_object_access_internals_t *ep,
  1388      Dwarf_Unsigned secnum,
  1389      enum RelocRela localr,
  1390      int *errcode)
  1391  {
  1392      struct generic_shdr *gshdr = 0;
  1393      Dwarf_Unsigned seccount = 0;
  1394      unsigned offsetsize = 0;
  1395      struct generic_rela *grp = 0;
  1396      Dwarf_Unsigned count_read = 0;
  1397      int res = 0;
  1398      unsigned oksec = 0;
  1399      enum RelocOffsetSize localoffsize = RelocOffset32;
  1400
  1401      /*  ASSERT: Caller guarantees localr is
  1402          a valid RelocRela  */
  1403      if (!ep) {
  1404          *errcode = DW_DLE_INTERNAL_NULL_POINTER;
  1405          return DW_DLV_ERROR;
  1406      }
  1407      offsetsize = ep->f_offsetsize;
  1408      seccount = ep->f_loc_shdr.g_count;
  1409      if (secnum >= seccount) {
  1410          *errcode = DW_DLE_ELF_SECTION_ERROR;
  1411          return DW_DLV_ERROR;
  1412      }
  1413      gshdr = ep->f_shdr +secnum;
  1414      if (is_empty_section(gshdr->gh_type)) {
  1415
  1416          return DW_DLV_NO_ENTRY;
  1417      }
  1418
  1419      res = this_rel_is_a_section_dwarf_related(ep,gshdr,
  1420          &oksec,errcode);
  1421      if (res == DW_DLV_ERROR) {
  1422          return res;
  1423      }
  1424      if (!oksec) {
  1425          return DW_DLV_OK;
  1426      }
  1427      /*  We will actually read these relocations. */
  1428      if (offsetsize == 64) {
  1429          localoffsize = RelocOffset64;
  1430      } else if (offsetsize == 32) {
  1431          localoffsize = RelocOffset32;
  1432      } else {
  1433          *errcode = DW_DLE_OFFSET_SIZE;
  1434          return DW_DLV_ERROR;
  1435      }
  1436      /*  ASSERT: localoffsize is now a valid enum value,
  1437          one of the two defined. */
  1438      res = _dwarf_elf_load_a_relx_batch(ep,
  1439          gshdr,&grp,&count_read,localr,localoffsize,errcode);
  1440      if (res == DW_DLV_ERROR) {
  1441          return res;
  1442      }
  1443      if (res == DW_DLV_NO_ENTRY) {
  1444          return res;
  1445      }
  1446      gshdr->gh_rels = grp;
  1447      gshdr->gh_relcount = count_read;
  1448      return DW_DLV_OK;
  1449  }
