  1596  int
  1597  _dwarf_load_elf_header(
  1598      dwarf_elf_object_access_internals_t *ep,int*errcode)
  1599  {
  1600      unsigned offsetsize = ep->f_offsetsize;
  1601      int res = 0;
  1602
  1603      res = validate_struct_sizes(errcode);
  1604      if (res != DW_DLV_OK) {
  1605          return res;
  1606      }
  1607
  1608      if (offsetsize == 32) {
  1609          res = elf_load_elf_header32(ep,errcode);
  1610      } else if (offsetsize == 64) {
  1611          if (sizeof(Dwarf_Unsigned) < 8) {
  1612              *errcode =  DW_DLE_INTEGER_TOO_SMALL;
  1613              return DW_DLV_ERROR;
  1614          }
  1615          res = elf_load_elf_header64(ep,errcode);
  1616      } else {
  1617          *errcode = DW_DLE_OFFSET_SIZE;
  1618          return DW_DLV_ERROR;
  1619      }
  1620      return res;
  1621  }
